package com.yeyamo_mobile.api.gamification_service.infrastructure.messaging;import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.gamification_service.application.GamificationService;import com.yeyamo_mobile.api.gamification_service.domain.XpActivity;
class GamificationEventConsumerTest{@Test void persistentReceiptMakesConsumerIdempotent()throws Exception{UUID id=UUID.randomUUID();var policy=mock(EventXpPolicy.class);var service=mock(GamificationService.class);var receipts=mock(ProcessedEventRepository.class);var activity=new XpActivity(id,"u",2,"LIKE","p1","SOCIAL",null,java.time.Instant.now());when(policy.map(any())).thenReturn(Optional.of(activity));when(receipts.existsById(id)).thenReturn(false,true);String raw="{\"eventId\":\""+id+"\",\"eventType\":\"interaction.like.added\",\"eventVersion\":1,\"correlationId\":\"c1\",\"payload\":{}}";var consumer=new GamificationEventConsumer(new ObjectMapper(),policy,service,receipts);consumer.consume(raw);consumer.consume(raw);verify(service,times(1)).apply(activity,"c1");verify(receipts,times(1)).save(any());}}
